krpano.action:
set(layer[tooltip].html, %1);
if(%2 != null,
	set(layer[tooltip].x, %2),
	copy(layer[tooltip].x, mouse.x); add(layer[tooltip].x, 5);
);
if(%3 != null,
	set(layer[tooltip].y, %3),
	copy(layer[tooltip].y, mouse.y); add(layer[tooltip].y, 25);
);
set(layer[tooltip].visible, true);

set(global_heading, 180);

set(global_heading2, 0);



calc(plugin[compass2_pointer].rotate, view.hlookat - global_heading);

calc(plugin[bac_hoa_gio].rotate, view.hlookat - global_heading2);

trace('Calling custom_loadscene with scene: ', get(name));

copy(previous_scene, scene[get(xml.scene)].name);

trace('Transitioning to scene: ', get(name), ', setting previous_scene to: ', get(previous_scene));

loadscene(get(linkedscene), null, MERGE, BLEND(1));

trace('Initializing tooltips for scene: ', get(scene[get(xml.scene)].name), ', previous_scene: ', get(previous_scene));

for(set(i,0), i LT hotspot.count, inc(i),

    if(hotspot[get(i)].linkedscene,

        callwith(hotspot[get(i)], add_all_the_time_tooltip2());

    );

);
